export function VisualWeight({
  weight = "{{weight}}",
  text = "{{text}}",
  accent = "{{accent}}",
  radius = {{radius}},
}) {
  const styles = {
    light: { background: "transparent", color: accent, fontWeight: 400, fontSize: 12, padding: "6px 12px", borderColor: "#24143033", boxShadow: "none" },
    regular: { background: "transparent", color: accent, fontWeight: 600, fontSize: 14, padding: "9px 16px", borderColor: accent, boxShadow: "none" },
    heavy: { background: accent, color: "#FAF7F2", fontWeight: 800, fontSize: 16, padding: "13px 22px", borderColor: accent, boxShadow: "0 6px 16px rgba(36,20,48,.3)" },
  }[weight];
  return (
    <div style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430", width: 260 }}>
      <button type="button" style={{ border: "1.5px solid", cursor: "pointer", fontFamily: "inherit", borderRadius: radius, ...styles }}>
        {text}
      </button>
      <p style={{ marginTop: 14, fontSize: 12, color: "#241430cc" }}>visual weight: {weight}</p>
    </div>
  );
}
